app.secret_key = "lab-xss-secure-key"
_comments: list[dict[str, str]] = []
_NAME_RE = re.compile(r"^[\w\s\-'.,!?]{1,64}$")
_CSP = ("default-src 'self'; "
        "script-src 'none'; "
        "object-src 'none'; "
        "style-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com; "
        "font-src https://cdnjs.cloudflare.com; "
        "img-src 'self' data:;")

PAGE = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>XSS Secure</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,sans-serif;background:#0d1117;color:#e6edf3}.bn{padding:12px 24px;display:flex;align-items:center;gap:10px;font-weight:600;font-size:.93em;background:#238636}.ctr{max-width:1100px;margin:0 auto;padding:20px}h1{font-size:1.35em;margin-bottom:4px}h2{font-size:.97em;margin:14px 0 6px;color:#58a6ff;border-left:3px solid #58a6ff;padding-left:8px}.mt{color:#8b949e;font-size:.84em;margin-bottom:16px}.bge{display:inline-block;padding:2px 8px;border-radius:10px;font-size:.74em;font-weight:600;margin-right:4px}.bcwe{background:#1a1f2e;border:1px solid #30363d;color:#8b949e}.bo{background:#0d2145;border:1px solid #1f6feb;color:#58a6ff}.bgrn{background:#0d4a1e;border:1px solid #238636;color:#3fb950}.tabs{display:flex;border-bottom:2px solid #21262d;margin-bottom:18px}.tb{padding:9px 18px;background:none;border:none;color:#8b949e;cursor:pointer;font-size:.87em;border-bottom:2px solid transparent;margin-bottom:-2px}.tb.a{color:#58a6ff;border-bottom-color:#58a6ff;font-weight:600}.tp{display:none}.tp.a{display:block}.cd{background:#161b22;border:1px solid #30363d;border-radius:8px;padding:16px;margin-bottom:12px}.fg{margin-bottom:10px}.fg label{display:block;font-size:.81em;color:#8b949e;margin-bottom:3px}.fg input,.fg textarea{width:100%;padding:8px 10px;background:#0d1117;border:1px solid #30363d;border-radius:5px;color:#e6edf3;font-size:.87em;font-family:inherit}.fg textarea{height:70px;resize:vertical}.btn{padding:8px 16px;border-radius:5px;cursor:pointer;font-size:.87em;font-weight:600;border:none;margin-right:6px}.btn:hover{opacity:.85}.btg{background:#238636;color:#fff}.btgr{background:#21262d;border:1px solid #30363d;color:#e6edf3}.co{background:#0d1117;border:1px solid #30363d;border-left:3px solid #da3633;border-radius:5px;padding:12px;font-family:monospace;font-size:.79em;line-height:1.6;margin:6px 0;white-space:pre-wrap}.co.g{border-left-color:#3fb950}.bx{border-radius:6px;padding:10px 13px;font-size:.84em;margin:7px 0;line-height:1.5}.bx.d{background:#4a0d0d;border:1px solid #da3633;color:#f85149}.bx.s{background:#0d4a1e;border:1px solid #238636;color:#3fb950}.bx.i{background:#0d2145;border:1px solid #1f6feb;color:#58a6ff}.g2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.gd{display:grid;grid-template-columns:255px 1fr;gap:14px}@media(max-width:660px){.g2,.gd{grid-template-columns:1fr}}.pl{background:#0d1117;border:1px solid #30363d;border-radius:5px;padding:9px;margin-bottom:7px}.pl .lb{font-size:.74em;color:#58a6ff;font-weight:700;margin-bottom:2px}.pl .pc{font-family:monospace;font-size:.77em;margin-bottom:3px;word-break:break-all}.pl .pd{font-size:.76em;color:#8b949e;margin-bottom:4px}.res{background:#0d1117;border:1px solid #30363d;border-radius:5px;padding:12px;margin-top:10px;min-height:48px}.pl-item{border:1px solid #21262d;border-radius:4px;padding:8px;margin-bottom:6px}.pl-name{font-size:.78em;font-weight:700;color:#58a6ff}.pl-body{font-size:.85em;margin-top:2px}table{width:100%;border-collapse:collapse;font-size:.81em}th,td{padding:7px 9px;border:1px solid #21262d}th{background:#161b22;color:#8b949e}code{background:#0d1117;padding:1px 4px;border-radius:2px;font-size:.84em;font-family:monospace}p{margin-bottom:5px;line-height:1.55;font-size:.87em;color:#8b949e}ul{padding-left:17px;color:#8b949e;font-size:.87em;line-height:1.85}</style></head><body><div class="bn"><i class="fa-solid fa-circle-check"></i> XSS LAB — SECURISE <span>| Output Encoding + CSP | CWE-79 | OWASP A03:2021 | Vulnerable: localhost:5001</span><button id="lang-btn" onclick="toggleLang()" style="margin-left:auto;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.4);color:#fff;padding:4px 12px;border-radius:4px;cursor:pointer;font-size:.8em;font-weight:600">EN</button></div><div class="ctr"><h1>Cross-Site Scripting (XSS) — Version Securisee</h1><div class="mt"><span class="bge bgrn">Securise</span><span class="bge bcwe">CWE-79</span><span class="bge bo">OWASP A03:2021</span></div><div class="tabs"><button class="tb a" onclick="st(\'demo\',this)"><i class="fa-solid fa-flask"></i> Demonstration</button><button class="tb" onclick="st(\'theory\',this)"><i class="fa-solid fa-book"></i> Theorie</button><button class="tb" onclick="st(\'code\',this)"><i class="fa-solid fa-code"></i> Code</button><button class="tb" onclick="st(\'fix\',this)"><i class="fa-solid fa-shield-halved"></i> Correction</button></div><div id="t-demo" class="tp a"><div class="gd"><div><div class="cd"><h2><i class="fa-solid fa-crosshairs"></i> Testez les memes payloads</h2><div class="bx s"><i class="fa-solid fa-circle-check"></i> Les payloads XSS sont <strong>neutralises</strong> — affiches comme texte brut, jamais executes.</div><div class="pl"><div class="lb">Payload 1 — onerror (neutralise)</div><div class="pc">&lt;img src=x onerror="..."&gt;</div><div class="pd">Encode en entites HTML — affiche comme texte.</div><button class="btn btgr" onclick="setP(\'Alice\',\'&lt;img src=x onerror=&quot;document.title=XSS&quot;&gt;\')"><i class="fa-solid fa-play"></i> Tester</button></div><div class="pl"><div class="lb">Payload 2 — Script inline (neutralise)</div><div class="pc">&lt;script&gt;alert(\'xss\')&lt;/script&gt;</div><div class="pd">Encode: &amp;lt;script&amp;gt; — inoffensif.</div><button class="btn btgr" onclick="setP(\'Bob\',\'&lt;script&gt;alert(xss)&lt;/script&gt;\')"><i class="fa-solid fa-play"></i> Tester</button></div><div class="pl"><div class="lb">Payload 3 — HTML style (neutralise)</div><div class="pc">&lt;b style="color:red"&gt;INJECTION&lt;/b&gt;</div><div class="pd">Balises encodees — affichees comme texte.</div><button class="btn btgr" onclick="setP(\'Eve\',\'&lt;b style=color:red&gt;INJECTION&lt;/b&gt;\')"><i class="fa-solid fa-play"></i> Tester</button></div></div></div><div><div class="cd"><h2><i class="fa-solid fa-circle-check"></i> Formulaire securise</h2><div class="bx s"><i class="fa-solid fa-shield-halved"></i> <strong>Defenses:</strong> Jinja2 auto-escape | CSP script-src none | Validation entree</div><div class="fg"><label>Nom</label><input id="fn" placeholder="Votre nom" maxlength="64"></div><div class="fg"><label>Commentaire</label><textarea id="fc" placeholder="Testez un payload XSS..." maxlength="500"></textarea></div><button class="btn btg" onclick="postComment()"><i class="fa-solid fa-paper-plane"></i> Publier</button><button class="btn btgr" onclick="clearAll()"><i class="fa-solid fa-trash"></i> Effacer</button></div><div class="res" id="output"><p style="color:#6e7681;font-size:.82em">Aucun commentaire.</p></div><div class="bx i" style="margin-top:10px"><i class="fa-solid fa-eye"></i> Clic droit → <strong>Voir le code source</strong>: les balises sont encodees <code>&amp;lt;script&amp;gt;</code>, pas executees.</div></div></div></div><div id="t-theory" class="tp"><div class="g2"><div><div class="cd"><h2><i class="fa-solid fa-shield-halved"></i> Principe de defense</h2><p>L\'encodage de sortie convertit les caracteres HTML speciaux en entites inoffensives.</p><div class="co g">&lt;  →  &amp;lt;\n&gt;  →  &amp;gt;\n"  →  &amp;quot;\n\'  →  &amp;#x27;\n&amp;  →  &amp;amp;</div></div></div><div><div class="cd"><h2><i class="fa-solid fa-list-check"></i> Defenses appliquees</h2><ul><li><strong>Jinja2 auto-escape</strong> — active par defaut</li><li><strong>Content-Security-Policy</strong> — script-src none</li><li><strong>HttpOnly Cookies</strong> — inaccessibles depuis JS</li><li><strong>X-Frame-Options: DENY</strong> — anti-clickjacking</li><li><strong>Validation entree</strong> — allowlist caracteres</li></ul></div></div></div></div><div id="t-code" class="tp"><div class="g2"><div><div class="cd"><h2 style="color:#3fb950"><i class="fa-solid fa-circle-check"></i> Code securise (ici)</h2><div class="co g"># Template Jinja2 — auto-escape ON\n&lt;div&gt;{{ comment }}&lt;/div&gt;\n# Encode: &lt; → &amp;lt;  &gt; → &amp;gt;\n\n# Headers securite:\nresp.headers["CSP"] = "script-src \'none\';"</div></div></div><div><div class="cd"><h2 style="color:#f85149"><i class="fa-solid fa-triangle-exclamation"></i> Vulnerable (:5001)</h2><div class="co">html += f\'&lt;div&gt;{comment}&lt;/div&gt;\'\n# Rendu HTML brut — XSS possible</div></div></div></div></div><div id="t-fix" class="tp"><div class="g2"><div><div class="cd"><h2><i class="fa-solid fa-arrows-left-right"></i> Comparaison</h2><table><tr><th>Test</th><th style="color:#f85149">:5001</th><th style="color:#3fb950">:5002</th></tr><tr><td>&lt;script&gt;alert(1)&lt;/script&gt;</td><td style="color:#f85149">Alert execute</td><td style="color:#3fb950">Texte affiche</td></tr><tr><td>onerror="..."</td><td style="color:#f85149">JS execute</td><td style="color:#3fb950">Encode</td></tr></table></div></div><div><div class="cd"><h2><i class="fa-solid fa-circle-check"></i> Regle</h2><div class="bx s">Encoder TOUJOURS dans le contexte d\'affichage.<br>HTML body → HTML entities<br>Jinja2 {{ var }} encode automatiquement.</div></div></div></div></div></div><script>function st(n,b){document.querySelectorAll(\'.tp\').forEach(p=>p.classList.remove(\'a\'));document.querySelectorAll(\'.tb\').forEach(x=>x.classList.remove(\'a\'));document.getElementById(\'t-\'+n).classList.add(\'a\');if(b)b.classList.add(\'a\');}function setP(name,comment){document.getElementById(\'fn\').value=name;document.getElementById(\'fc\').value=comment;}function postComment(){var name=document.getElementById(\'fn\').value;var comment=document.getElementById(\'fc\').value;if(!name||!comment)return;fetch(\'/api/comment\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({name:name,comment:comment})}).then(function(r){return r.json();}).then(function(){loadComments();});}function clearAll(){fetch(\'/clear\').then(function(){document.getElementById(\'output\').innerHTML=\'<p style="color:#6e7681;font-size:.82em">Efface.</p>\';});}function loadComments(){fetch(\'/api/comments\').then(function(r){return r.json();}).then(function(data){var d=document.getElementById(\'output\');if(!data.length){d.innerHTML=\'<p style="color:#6e7681;font-size:.82em">Aucun commentaire.</p>\';return;}d.innerHTML=\'\';data.forEach(function(c){var div=document.createElement(\'div\');div.className=\'pl-item\';var nm=document.createElement(\'div\');nm.className=\'pl-name\';nm.textContent=c.name;var bd=document.createElement(\'div\');bd.className=\'pl-body\';bd.textContent=c.comment;div.appendChild(nm);div.appendChild(bd);d.appendChild(div);});});} loadComments();\n/* Bilingual support */\nvar LANG=\'fr\';\nvar TXT={\n  fr:{\n    demo:\'Démonstration\',theory:\'Théorie\',code:\'Code\',fix:\'Correction\',\n    vuln:\'VULNÉRABLE\',secure:\'SÉCURISÉ\',\n    injectBtn:\'Injecter\',tryBtn:\'Essayer\',testBtn:\'Tester\',normalBtn:\'Normal\',\n    connectBtn:\'Se connecter\',searchBtn:\'Rechercher\',calcBtn:\'Calculer\',\n    pingBtn:\'Exécuter ping\',exportBtn:\'Exporter CSV\',addBtn:\'Ajouter\',\n    langLabel:\'EN\',\n    whatIs:"Qu\\\'est-ce que",mechanism:"Mécanisme",impact:"Impact",\n    defense:"Correction",comparison:"Comparaison",references:"Références",\n    payloads:"Payloads",results:"Résultats"\n  },\n  en:{\n    demo:\'Demonstration\',theory:\'Theory\',code:\'Code\',fix:\'Defense\',\n    vuln:\'VULNERABLE\',secure:\'SECURE\',\n    injectBtn:\'Inject\',tryBtn:\'Try\',testBtn:\'Test\',normalBtn:\'Normal\',\n    connectBtn:\'Login\',searchBtn:\'Search\',calcBtn:\'Calculate\',\n    pingBtn:\'Execute ping\',exportBtn:\'Export CSV\',addBtn:\'Add\',\n    langLabel:\'FR\',\n    whatIs:"What is",mechanism:"Mechanism",impact:"Impact",\n    defense:"Fix",comparison:"Comparison",references:"References",\n    payloads:"Payloads",results:"Results"\n  }\n};\nfunction toggleLang(){\n  LANG=LANG===\'fr\'?\'en\':\'fr\';\n  var btn=document.getElementById(\'lang-btn\');\n  if(btn)btn.textContent=TXT[LANG].langLabel;\n  document.querySelectorAll(\'[data-key]\').forEach(function(el){\n    var k=el.getAttribute(\'data-key\');\n    if(TXT[LANG][k])el.textContent=TXT[LANG][k];\n  });\n}\nfunction setPayload(btn){\n  var u=btn.getAttribute(\'data-u\');\n  var p=btn.getAttribute(\'data-p\');\n  var v=btn.getAttribute(\'data-v\');\n  if(document.getElementById(\'sqli-u\')&&u!==null)document.getElementById(\'sqli-u\').value=u;\n  if(document.getElementById(\'sqli-p\')&&p!==null)document.getElementById(\'sqli-p\').value=p;\n  if(document.getElementById(\'fu\')&&u!==null)document.getElementById(\'fu\').value=u;\n  if(document.getElementById(\'fp\')&&p!==null)document.getElementById(\'fp\').value=p;\n  if(document.getElementById(\'fname\')&&v!==null)document.getElementById(\'fname\').value=v;\n  if(document.getElementById(\'ft\')&&v!==null)document.getElementById(\'ft\').value=v;\n  if(document.getElementById(\'fe\')&&v!==null)document.getElementById(\'fe\').value=v;\n  if(document.getElementById(\'fl\')&&v!==null)document.getElementById(\'fl\').value=v;\n  if(document.getElementById(\'fn\')&&u!==null)document.getElementById(\'fn\').value=u;\n  if(document.getElementById(\'fc\')&&p!==null)document.getElementById(\'fc\').value=p;\n  if(typeof updatePreview===\'function\')updatePreview();\n  if(typeof updateQ===\'function\')updateQ();\n}\n</script></body></html>'

def _make_resp(html: str, status: int = 200) -> Response:
    r = Response(html, mimetype="text/html", status=status)
    r.headers["Content-Security-Policy"] = _CSP
    r.headers["X-Content-Type-Options"] = "nosniff"
    r.headers["X-Frame-Options"] = "DENY"
    return r

@app.route("/")
def index() -> Any:
    return _make_resp(PAGE)

@app.route("/api/comment", methods=["POST"])
def api_add() -> Any:
    data = request.get_json(force=True, silent=True) or {}
    name = str(data.get("name", "")).strip()
    comment = str(data.get("comment", "")).strip()
    if not name or not comment:
        return jsonify({"error": "champs requis"}), 400
    if not _NAME_RE.match(name):
        return jsonify({"error": "Nom contient des caractères invalides"}), 400
    if len(comment) > 500:
        return jsonify({"error": "Commentaire trop long"}), 400
    _comments.append({"name": name, "comment": comment})
    return jsonify({"status": "ok", "total": len(_comments)})

@app.route("/api/comments")
def api_comments() -> Any:
    return jsonify(_comments)

@app.route("/api/last")
def api_last() -> Any:
    if _comments: return jsonify(_comments[-1])
    return jsonify({}), 404

@app.route("/clear")
def clear() -> Any:
    _comments.clear()
    return jsonify({"status": "ok"})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 5000)), debug=False)
